local ServiceProvider = require(script.Parent.ServiceProvider)

return function()
	describe("ServiceProvider", function()
		local provider

		beforeEach(function()
			provider = ServiceProvider.new(nil, {}, {})
		end)

		it("should dispose correctly", function()
			local disposeCount = 0
			local mockService = {
				Dispose = function()
					disposeCount = disposeCount + 1
				end,
			}

			-- 添加一个需要销毁的服务到历史记录中
			provider:AddCreatedObjectHistory({
				ImplementationInstance = false,
			}, mockService)

			provider:Dispose()

			-- 验证服务被正确销毁
			expect(disposeCount).to.equal(1)
			expect(provider.DisposeCalled).to.equal(true)
		end)

		describe("CreatedObjectHistory", function()
			it("should not add duplicate objects to history", function()
				local mockService = {
					name = "test",
				}
				local descriptor = {
					ImplementationInstance = false,
				}

				-- 添加同一个对象两次
				provider:AddCreatedObjectHistory(descriptor, mockService)
				provider:AddCreatedObjectHistory(descriptor, mockService)

				-- 验证历史记录中只有一个实例
				expect(#provider._createdObjectHistory).to.equal(1)
			end)

			it("should handle ImplementationInstance correctly", function()
				local mockInstanceService = {
					name = "instanceTest",
					Dispose = function() end,
				}
				local descriptor = {
					ImplementationInstance = true,
				}

				provider:AddCreatedObjectHistory(descriptor, mockInstanceService)
				provider:Dispose()

				expect(#provider._createdObjectHistory).to.equal(0)
			end)

			it("should handle cache and history together", function()
				local mockService = {
					name = "cacheTest",
				}
				local descriptor = {
					ServiceType = {},
					ImplementationInstance = false,
				}

				-- 测试缓存和历史记录的交互
				provider:AddCache(descriptor, "testService", mockService)
				provider:AddCreatedObjectHistory(descriptor, mockService)

				local cached, result = provider:TryGetCachedService(descriptor, "testService")
				expect(cached).to.equal(true)
				expect(result).to.equal(mockService)
				expect(#provider._createdObjectHistory).to.equal(1)
			end)
		end)
	end)
end
